// lib
namespace Lib;

// Project A: a dependency-free data type, no MessagePack reference.
public class MyObject
{
    public int Id { get; set; }
    public string? Name { get; set; }
}

// app
using Lib;
using MessagePack;

namespace App;

// Partial (so MsgPack019 stays quiet), but it does not implement
// IMessagePackFormatter<MyObject>, so the generator has no data type to
// generate for. The new build reports MsgPack020 here; the old build has
// no such rule (and no [GeneratedMessagePackFormatter] attribute at all).
[GeneratedMessagePackFormatter]
internal partial class MyObjectFormatter
{
}

internal static class Program
{
    private static void Main()
    {
        var value = new MyObject { Id = 1, Name = "a" };
        System.Console.WriteLine(value.Id);
    }
}
